import sys

def determine_winner():
    try:
        # Read the number of stones from input
        N = int(input())

        if N <= 1:
            return "Alice"
        elif (N - 1) % 2 == 0:
            return "Bob"
        else:
            return "Draw"
    except ValueError:
        print("Invalid input. Please enter a valid integer.")
        sys.exit(1)

# Call the function and print the result
winner = determine_winner()
print(winner)
